-- 프로토타입 위키(5장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('17829409-3261-5191-8145-78a38e939203'::uuid, '5장 · 1절 · 위생급배수 · 급수물을올리는4가지방법', '급수방식 (수도직결 · 고가수조 · 압력탱크 · 부스터)', '수도직결: 본관 압력으로 직접 — 저층·위생적. 고가수조: 옥상 탱크에서 중력 급수 — 압력 일정·단수 대비, 오염·구조 부담.', '["압력탱크: 밀폐 탱크 가압 — 압력 변동. 부스터펌프: 펌프 직송 — 옥상탱크 불필요, 현대 표준.", "비교·암기 — ''직결(수돗물 그대로) - 고가(올려놓고 떨어뜨림) - 압력탱크·부스터(펌프로 밀어줌)'' — 압력을 어디서 얻나로 구분."]'::jsonb, false),
  ('593c04c3-e2f9-5b94-b9d0-bbcdc43e79f3'::uuid, '5장 · 1절 · 위생급배수 · 급수물을올리는4가지방법', '급탕방식 (개별식 · 중앙식)', '개별식: 사용처마다 순간·저탕 급탕기 — 배관 짧고 열손실 적음(주택). 중앙식: 기계실에서 일괄 가열·순환 — 대규모(호텔·병원).', '[]'::jsonb, false),
  ('0be4c466-c270-5cae-96f7-e212edd3cd07'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '배수 · 통기', '배수관은 물이 흐르고, 통기관은 공기를 넣어 배수를 원활하게 하고 트랩 봉수를 보호하는 시스템.', '["''배수는 물길, 통기는 숨길'' — 둘은 세트."]'::jsonb, false),
  ('b785b87e-f6e9-5379-a3a5-ffb6279603ff'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '트랩과 봉수', '트랩: 배수관 도중 물을 고이게 만든 굴곡(S·P·U자 등). 봉수: 그 고인 물 — 하수 가스·냄새·벌레의 역류를 막는 물마개.', '["봉수 깊이 50~100mm 표준. ※확인."]'::jsonb, true),
  ('0babc3f8-6dc8-525d-a7cb-2a3f8b872171'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '봉수파괴', '봉수가 사라져 냄새가 올라오는 현상.', '["원인: 자기사이펀(배수 시 딸려 나감), 흡출·분출(다른 층 배수의 압력 변동), 증발, 모세관(머리카락). 대책: 통기관 설치가 근본.", "비교·암기 — 봉수파괴 원인 대부분이 ''관 속 압력 변동'' — 그래서 답은 통기관. 원인–대책을 한 쌍으로."]'::jsonb, false),
  ('5d85c00d-7074-5465-b0f8-d2336f78343b'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '통기관 (각개 · 루프 · 신정)', '각개통기: 기구마다 — 가장 확실. 루프통기: 여러 기구 묶어 하나로 — 경제적. 신정통기: 배수 수직관 상단을 연장해 대기 개방 — 최소한의 기본.', '[]'::jsonb, false),
  ('8aae1ab2-d428-52ad-86f3-d6c5df2d7242'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '오수 · 우수 분류', '오수(변기)·잡배수(세면·주방)·우수(빗물)를 분리 배관. 분류식 하수 지역은 오수만 처리장으로 — 오접(우수관에 오수 연결)이 대표 하자.', '[]'::jsonb, false),
  ('dd5fb2fa-ca92-55d8-88c3-e51f08a1b33e'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '정화조 · 오수처리시설', '하수처리장 미연결 지역에서 오수를 자체 정화해 방류하는 시설. 규모에 따라 단독정화조·오수처리시설 구분. ※기준 확인.', '[]'::jsonb, true),
  ('8d496038-0d1e-5b7e-9bc1-f63e6e70fc46'::uuid, '5장 · 1절 · 위생급배수 · 배수와트랩냄새와의싸움', '위생기구', '대변기(세정밸브식·로탱크식)·세면기·싱크 등. 급수전 오염 방지 — 토수구 공간 확보(역류 방지).', '[]'::jsonb, false),
  ('357d4f75-c83c-5e2c-8a1e-dbf91abff3c6'::uuid, '5장 · 1절 · 위생급배수 · 배관재료와부속', '배관재료 (강관 · 동관 · PVC · PB · STS)', '강관(내압 — 부식 대책 필요), 동관(내식·열전도 — 급탕), PVC(경제적 — 배수), PB(유연 — 세대 급수·난방), 스테인리스(내식 최고 — 급수 표준화 흐름).', '["선정 축: 압력·온도·부식·위생 — ''어디에 어떤 물이 흐르나''."]'::jsonb, false),
  ('69aa75b9-59f4-5dfc-9b0c-9a2d45995918'::uuid, '5장 · 1절 · 위생급배수 · 배관재료와부속', '밸브 (게이트 · 글로브 · 체크 · 볼)', '게이트: 전개·전폐(차단용, 저항 적음). 글로브: 유량 조절. 체크: 역류 방지(한 방향). 볼: 90도 회전 개폐(신속).', '["비교·암기 — ''게이트는 끊고, 글로브는 조절하고, 체크는 못 돌아오게, 볼은 빨리'' — 역할 한 줄씩."]'::jsonb, false),
  ('59109588-2b86-5b5b-a474-ef0c70323de9'::uuid, '5장 · 1절 · 위생급배수 · 배관재료와부속', '배관 보온재', '결로 방지(급수·냉수관)와 열손실 방지(급탕·난방관) 피복. 보온 누락 부위 결로가 ''누수 오인'' 하자의 단골.', '[]'::jsonb, false),
  ('8edcae36-5b94-5615-9acf-05140f9cfb7e'::uuid, '5장 · 1절 · 위생급배수 · 배관재료와부속', '수격작용 (워터해머)', '밸브 급폐쇄 시 유속의 관성으로 관 내 압력이 급상승해 배관을 때리는 현상(쿵 소리·진동).', '["대책: 에어챔버·수격방지기 설치, 급폐쇄 밸브 지양, 유속 낮게 설계."]'::jsonb, false),
  ('3a2eb209-c72f-5fac-a9bd-f64d9a7dfaf1'::uuid, '5장 · 2절 · 공조난방 · 난방', '난방방식 (증기 · 온수 · 복사 · 지역난방)', '증기: 잠열 이용 — 방열 크고 빠름, 쾌적성·제어 낮음(공장). 온수: 현열 — 부드럽고 제어 쉬움. 복사: 바닥·패널 가열 — 쾌적성 최고(온돌). 지역난방: 열병합 플랜트에서 열 공급 — 대단지.', '["비교·암기 — 우리나라 아파트 = 복사(온돌) + 지역난방 조합이 표준이라는 맥락으로 기억."]'::jsonb, false),
  ('b437e5c5-a32d-5aaf-bb8e-3d97b4b73bbc'::uuid, '5장 · 2절 · 공조난방 · 난방', '보일러', '물을 가열해 증기·온수를 만드는 열원 기기(주철·노통연관·수관·관류식). 안전장치(안전밸브·저수위 차단) — 검사 대상 기기.', '[]'::jsonb, false),
  ('5eec5d77-a40b-5a69-8230-7ba8e457a52a'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '공조기 (AHU)', '필터+코일(냉온수)+가습+송풍기로 공기를 처리해 덕트로 보내는 중앙 공조 기기.', '["공조의 4요소: 온도·습도·기류·청정도 — AHU는 이 넷을 한 번에 처리하는 상자."]'::jsonb, false),
  ('19f34fb9-5a5d-550d-b0f7-16d076f6f05a'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '팬코일유닛 (FCU)', '실별로 놓는 소형 코일+팬 유닛. 냉온수 배관만 받아 실내 공기를 순환 처리 — 개별 제어.', '["비교·암기 — AHU(중앙에서 공기를 만들어 보냄=전공기 방식) ↔ FCU(물을 보내 실에서 처리=수방식) — 무엇을 반송하나로 구분."]'::jsonb, false),
  ('781a55f5-c73e-5d17-94c1-8b198e8efa24'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '시스템에어컨 (EHP · GHP)', '실외기 1대에 여러 실내기를 연결한 냉매식 개별공조. EHP(전기 히트펌프)·GHP(가스엔진) — 중소 건물 표준.', '[]'::jsonb, false),
  ('67b704f8-c13f-5073-afa6-53ee8fa91d68'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '덕트 · 디퓨저', '덕트: 공기 반송 통로(저속·고속). 디퓨저: 취출구(공기를 실내에 확산). 풍속·형상 — 소음·반송동력 관리.', '[]'::jsonb, false),
  ('cc607cc0-98f0-51df-ac56-b8034fcf624a'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '댐퍼 · 방화댐퍼', '댐퍼: 덕트 내 풍량 조절판. 방화댐퍼: 방화구획 관통 덕트에서 화재 시 자동 폐쇄(온도퓨즈·연동) — 구획 관통부 필수 부속.', '["방화구획을 덕트가 뚫으면 반드시 방화댐퍼 — 4장 방화구획과 연결되는 포인트."]'::jsonb, false),
  ('bab3176e-436f-596a-a3d8-66db8e651491'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '환기방식 (1종 · 2종 · 3종)', '1종: 급기+배기 모두 기계(압력 제어 자유). 2종: 급기만 기계(실내 정압 — 청정실·수술실). 3종: 배기만 기계(실내 부압 — 화장실·주방).', '["비교·암기 — ''들이밀면 2종(깨끗한 방), 빼내면 3종(더러운 방), 둘 다면 1종'' — 정압·부압의 논리로 암기. 시험 최다 출제."]'::jsonb, false),
  ('b092c23f-2fb9-5a8d-9347-4c802de7a896'::uuid, '5장 · 2절 · 공조난방 · 공조공기의4요소를다루는일', '전열교환기 (ERV)', '배기의 열·습기를 급기에 회수하는 환기 기기. 환기하면서 에너지 손실 최소화 — 기밀 건물·공동주택 의무 환기의 표준.', '[]'::jsonb, false),
  ('3ef066da-22fa-5a44-922c-67498ada15c2'::uuid, '5장 · 2절 · 공조난방 · 열원기기', '냉동기 (터보 · 흡수식)', '터보(원심): 전기 압축식 — 대용량·고효율. 흡수식: 증기·가스 열로 구동(냉매 물+흡수제) — 전력 부담 적고 폐열 활용.', '["비교·암기 — 터보(전기로 압축) ↔ 흡수식(열로 구동) — 구동 에너지로 구분. ''전기 아끼려면 흡수식''."]'::jsonb, false),
  ('eabcaff2-d461-5785-b87f-d338eb0e54e0'::uuid, '5장 · 2절 · 공조난방 · 열원기기', '냉각탑', '냉동기 응축열을 냉각수 증발로 대기에 버리는 옥상 설비. 백연·소음·레지오넬라(수질 관리) 이슈.', '[]'::jsonb, false),
  ('df71f24f-814f-505e-b6d1-fd36464766b4'::uuid, '5장 · 2절 · 공조난방 · 열원기기', '히트펌프', '냉매 사이클을 역전시켜 냉방·난방을 한 기기로 — 투입 전기보다 많은 열을 옮기는(성적계수 COP) 고효율 기기.', '[]'::jsonb, false),
  ('40502650-8b2e-54f0-add6-1eebd2f383fe'::uuid, '5장 · 2절 · 공조난방 · 열원기기', '클린룸 · 항온항습', '청정도(파티클)·온습도를 정밀 관리하는 특수 공조. 반도체 FAB·병원 수술부 — 필터(HEPA·ULPA)+기류 방식(층류)이 핵심.', '[]'::jsonb, false),
  ('70cecce8-3557-5ea7-92c6-630867b19eca'::uuid, '5장 · 3절 · 소방전기 · 소화설비물로끄는시스템', '옥내소화전', '건물 내 초기 소화용 수동 설비(호스+노즐). 방수압·방수량 기준, 수원 확보. ※수치 확인.', '[]'::jsonb, true),
  ('5df32a2d-d334-51ba-b98c-d509d99d6d75'::uuid, '5장 · 3절 · 소방전기 · 소화설비물로끄는시스템', '스프링클러 (습식 · 건식 · 준비작동식)', '화재열로 헤드가 개방되어 자동 살수하는 설비.', '["습식: 배관에 항상 물(표준·즉시 방수). 건식: 배관에 압축공기(동파 우려 구역). 준비작동식: 감지기 작동+헤드 개방의 2단계(오작동 수손 방지 — 전산실·주차장).", "비교·암기 — ''물 채워 대기(습식) - 공기 채움(건식) - 이중 확인(준비작동)'' — 배관 속에 뭐가 들었나로 구분."]'::jsonb, false),
  ('bafbaed5-67b0-5b5d-8ed4-068709412ce7'::uuid, '5장 · 3절 · 소방전기 · 소화설비물로끄는시스템', '옥외소화전 · 연결송수관', '옥외소화전: 건물 외부 소화전. 연결송수관: 소방차가 물을 보내 고층에서 소방대가 쓰는 배관(송수구+방수구) — ''소방관용 수직 파이프''.', '[]'::jsonb, false),
  ('2923ec17-98c8-5c1c-8162-651192e8f15b'::uuid, '5장 · 3절 · 소방전기 · 경보피난제연', '감지기 (차동식 · 정온식 · 연기식)', '차동식: 온도 상승률 감지(거실·사무실 일반). 정온식: 일정 온도 도달 감지(주방·보일러실 — 평소 열 나는 곳). 연기식: 연기 감지(복도·계단·침실 — 조기 감지).', '["비교·암기 — ''평소 뜨거운 곳은 정온식'' — 주방에 차동식을 달면 오작동한다는 논리로 암기."]'::jsonb, false),
  ('b58cd34e-4b95-504c-b88d-cbb4fd48b7c6'::uuid, '5장 · 3절 · 소방전기 · 경보피난제연', '제연설비', '화재 연기를 제어(배출·차단·가압)해 피난·소화 활동을 돕는 설비. 거실 제연(배연)과 부속실 제연(계단실 가압 — 연기 침입 차단)으로 구분.', '[]'::jsonb, false),
  ('b3dc36e7-381a-553c-b543-7c99143f98ac'::uuid, '5장 · 3절 · 소방전기 · 경보피난제연', '피난설비 (유도등 · 완강기)', '유도등(피난구·통로 유도), 완강기(속도 조절 하강 기구), 피난사다리·구조대 등. 상시 점등·장애물 없는 유지관리가 실무 포인트.', '[]'::jsonb, false),
  ('8cfb2dfa-c29c-57c6-9ac1-425d4cb7f0d2'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '수변전설비 · 변압기', '한전 고압(특고압)을 받아 건물용 저압으로 낮추는 설비(수전–변압–배전). 변압기·차단기·보호계전기로 구성 — 전기실.', '["전기의 흐름: 수전 - 변압 - 간선 - 분전반 - 부하. 이 한 줄이 건물 전기의 지도."]'::jsonb, false),
  ('4f7a920b-032c-54d8-99f5-05a7924ac3dd'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '간선 · 분전반', '간선: 전기실에서 각 층·구역으로 가는 굵은 배선. 분전반: 간선을 받아 회로별 차단기로 나누는 반.', '[]'::jsonb, false),
  ('ce9cea77-f791-5c41-9536-4f1bf6afb39d'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '접지', '전기설비의 이상 전류를 땅으로 흘려보내는 안전 조치. 감전·화재 방지의 기본.', '["접지 저항값·통합 접지 등 규정 — 감전 재해 예방과 직결(안전기사 연계 포인트). ※기준 확인."]'::jsonb, true),
  ('952c5d4a-fea9-55cf-b018-3150c18475eb'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '피뢰설비', '낙뢰를 받아 안전하게 대지로 유도하는 설비(수뢰부·인하도선·접지극). 높이 20m 이상 건물 설치 의무. ※기준 확인.', '[]'::jsonb, true),
  ('bee96d93-27e4-55f0-9723-d034cbb6186e'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '비상발전기 · UPS', '비상발전기: 정전 시 소방·비상 부하에 전력 공급(기동 시간 존재). UPS: 무정전 전원장치 — 배터리로 끊김 없이(전산·의료).', '["비교·암기 — 발전기(수십 초 뒤 공급, 장시간) ↔ UPS(0초 무정전, 단시간) — 조합해서 쓰는 관계."]'::jsonb, false),
  ('7a3d9038-d2da-5722-9697-289a31ecea91'::uuid, '5장 · 3절 · 소방전기 · 전기받아서나누고지키는순서', '조도 · 조명설비', '조도(lx): 밝기의 기준 지표 — 용도별 기준 조도. LED 표준화·조명 제어(재실 감지)로 에너지 절감.', '[]'::jsonb, false),
  ('7c85003d-04a0-54be-8100-ef23e1918413'::uuid, '5장 · 3절 · 소방전기 · 승강에너지', '승강기 (로프식 · 유압식)', '로프식: 권상기+균형추 — 중고층 표준(기계실 유무 타입). 유압식: 유압 잭으로 밀어 올림 — 저층·화물.', '["건축 시공과의 접점: 승강로 수직 정밀도·피트 방수·기계실(또는 MRL) 계획."]'::jsonb, false),
  ('bbaa304a-5e12-5fd9-80d8-c5df7d5df91e'::uuid, '5장 · 3절 · 소방전기 · 승강에너지', '에스컬레이터', '연속 수송 계단. 수송 능력 큼 — 판매시설. 끼임 사고 방지 안전장치·측면 방호.', '[]'::jsonb, false),
  ('b3ba2964-a19c-50d6-a913-e2de841b3b5b'::uuid, '5장 · 3절 · 소방전기 · 승강에너지', 'BEMS', '건물 에너지를 계측·분석·제어하는 관리 시스템. 에너지 사용을 ''보이게'' 해서 절감 — 일정 규모 공공건물 의무화 흐름. ※확인.', '[]'::jsonb, true),
  ('57798509-169f-57cb-81ed-807acc7dc670'::uuid, '5장 · 3절 · 소방전기 · 승강에너지', '신재생에너지 (태양광 · 지열 · 연료전지)', '태양광(PV): 지붕·벽 발전. 지열: 땅속 연중 일정 온도를 히트펌프 열원으로. 연료전지: 수소·가스의 전기화학 발전(전기+열 동시).', '["제로에너지건축(ZEB) 의무화와 연결 — 패시브(수요 절감)+액티브(고효율)+신재생(생산)의 3단 논리."]'::jsonb, false)
) as v(id, section, title, definition, points, flagged)
cross join (select id from auth.users limit 1) as u;
